        }
      }
      if (failed.length && ok > 0) {
        this.log(`  Audio retry pass · ${failed.length} cue(s)`);
        for (const item of failed.slice(0, 12)) {
          const good = await runCue(item.kind, item.id, item.hint || '');
          if (good) ok += 1;
        }
      }
      this.log(`  Audio preload finished · ${ok}/${queue.length}`);
    };

    this.log(`  Fetching pack metadata · effects=${effectIds.length} · movies=${movieIds.length}`);
    await Promise.all([
      ...effectIds.map((id) =>
        fetchEffectPack(id, { enemy: this.enemySide }).catch((e) => {
          this.log(`  effect-pack ${id}: ${e.message || e}`);
          return null;
        }),
      ),
      ...movieIds.map((id) =>
        fetchEffectPack(id, { enemy: this.enemySide }).catch((e) => {
