    );
    await withTimeout(preloadAudioSafe(), audioBudget, 'audio preload').catch((e) => {
      this.log(`  Audio preload moved on: ${e.message || e}`);
    });
    scope.assertCurrent();
    if (this.statusEl) this.statusEl.textContent = 'Loading movies / effects…';

    this._moviesPrepared = new Map();
    const movieBudget = onSite ? 180000 : 180000;
    for (const id of movieIds) {
      scope.assertCurrent();
      try {
        const pack = await fetchEffectPack(id, { enemy: this.enemySide });
        scope.assertCurrent();
        if (pack?.usm?.rel) {
          this._moviesPrepared.set(id, pack);
          this.log(`  Movie preload ${id}…`);
          await withTimeout(
            this.usm?.preloadFromAssetRel?.(pack.usm.rel, {
              stamp: pack.usm.stamp || '',
            }),
            movieBudget,
            `movie ${id}`,
          );
        } else {
          this.log(`  setupMovie ${id}: no USM (${pack?.media || 'missing'})`);
        }
      } catch (e) {
        this.log(`  setupMovie preload ${id}: ${e.message || e}`);
      }
    }

    scope.assertCurrent();
    this._fxPrepared.clear();
    this.lwf?.clear?.();
    let loaded = 0;
    const concurrency = onSite ? 2 : 3;
    this.log(`  Loading effect LWFs · ${effectCmds.length}`);
    for (let i = 0; i < effectCmds.length; i += concurrency) {
      scope.assertCurrent();
      const batch = effectCmds.slice(i, i + concurrency);
      await Promise.all(
        batch.map(async (cmd) => {
          const lease = scope.lease({
            label: `effect ${cmd.effectId}`,
            idleMs: onSite ? 40000 : 120000,
          });
          try {
            const ok = await lease.race(this._prepareEffect(cmd, lease));
            scope.assertCurrent();
            if (ok) loaded += 1;
          } catch (e) {
            this.log(`  effect ${cmd.effectId}: ${e.message || e}`);
          } finally {
            scope.release(lease);
          }
          scope.assertCurrent();
          if (this.statusEl) {
            this.statusEl.textContent = `Loading LWF ${loaded}/${effectCmds.length}…`;
          }
        }),
      );
    }

    scope.assertCurrent();
    this.log('  Loading characters…');
    try {
      await withTimeout(this.chara?.loadAll?.(), onSite ? 60000 : 180000, 'chara load');
      scope.assertCurrent();
      this.log('  Characters ready');
    } catch (e) {
      this.log(`  Chara load moved on: ${e.message || e}`);
    }

    scope.assertCurrent();
    this.log(
      `Preload done · LWF=${loaded}/${effectCmds.length}` +
        ` · USM=${this._moviesPrepared?.size || 0}/${movieIds.length}` +
        ` · SE=${seIds.size} · voice=${voiceIds.size}`,
    );
    const seSched = [...this.commands]
      .filter((c) => c.type === 'playSe' || c.type === 'playSeVer2' || c.type === 'playSeLife')
      .slice(0, 12)
      .map((c) => `${c.cueId}@f${c.frame || 0}`)
      .join(', ');
    if (seSched) this.log(`  SE schedule (first): ${seSched}`);
    const voSched = [...this.commands]
      .filter((c) => c.type === 'playVoice')
      .map((c) => `${c.cueId}@f${c.frame || 0}`)
      .join(', ');
    if (voSched) this.log(`  Voice schedule: ${voSched}`);
    if (!this.attackerCard?.found) this.log('  WARN: attacker card missing — set Attacker card id');
    if (!this.enemyCard?.found) this.log('  WARN: enemy card missing — set Enemy card id');
  }

  _loop() {
    const frameSec = 1 / FPS;
    // Steady pacing: the game logic runs at 30 fps, so drawing on every 60/90/120 Hz screen
    // refresh repeated work without new frames and made slower phones stutter. Recording and
    // "smooth30: false" keep drawing on every refresh.
    const paced = globalThis.__forgeAnimation?.smooth30 !== false;
    const slotMs = 1000 / FPS - 4;
    const tick = (now) => {
      if (!this.playing) return;
      if (paced && !this.onRecordFrame && this._lastTickMs != null && now - this._lastTickMs < slotMs) {
        this.raf = requestAnimationFrame(tick);
        return;
      }

      if (this._usmStartGate) {
        this._lastTickMs = now;
        this._wallEpochMs = null;
        this.lwf?.renderOnly?.();
        this.chara?.renderOnly?.();
        this.bg?.lwf?.renderOnly?.();
        this.usm?.clips?.forEach?.((c) => {
          try {
            this.usm._blitClip?.(c);
          } catch {

          }
        });
