      const usmLive = !!this.usm?.hasActiveClips?.();

      if (usmLive) {
        syncUsmAndLwf(this.usm, this.lwf, this.chara);
      }

      if (recording) {

        this._advance(this.step);
        this.forgeVisual?.tick(frameSec);
        const visualSteps = is2xMode ? 2 : 1;
        const visualSec = frameSec * visualSteps;
        if (this.pauseRemain > 0) {

          this.usm?.setAbPause?.(true);
          this.lwf?.tickEffects?.(this.phase, this.frame, visualSec, 1, {
            unpausableOnly: true,
          });
          this.screenFade?.tick?.(visualSec);
        } else {
          syncUsmAndLwf(this.usm, this.lwf, this.chara);
          this.usm?.syncMasterTimer?.(frameSec);
          this.lwf?.tickEffects?.(this.phase, this.frame, visualSec);
          if (!this.forgeVisual?.usesNativeCharacterClock) this.chara?.tick?.(visualSteps, FPS);
          this.bg?.tick?.(visualSec);
          this.screenFade?.tick?.(visualSec);
        }
        steps = 1;
        this._lastTickMs = now;
      } else {
        // Real-time clock: the picture follows the wall clock, like the sound does. A slow frame
        // or a short hitch (loading, garbage collection) is caught up over the next few frames
        // instead of being dropped, so voices, music and movie sound stay on the picture.
        // Only when this phone is more than a second behind is the backlog given up.
        this._lastTickMs = now;
        // Step boundaries sit half a step away from screen refreshes, so timing jitter can't make
        // frames alternate between 0 and 2 steps.
