          due -= 1;
          steps += 1;
        }
        this.accum = 0;
        const visualSec = steps * frameSec * rate;

        if (this.pauseRemain > 0) {
          this.lwf?.tickEffects?.(this.phase, this.frame, visualSec, 1, {
            unpausableOnly: true,
          });
          this.screenFade?.tick?.(visualSec);
        } else if (!this._usmStartGate && visualSec > 0) {
          this.lwf?.tickEffects?.(this.phase, this.frame, visualSec);
          if (!this.forgeVisual?.usesNativeCharacterClock) this.chara?.tick?.(visualSec * FPS, FPS);
          this.bg?.tick?.(visualSec);
          this.screenFade?.tick?.(visualSec);
        }
      }

      if (this.pauseRemain <= 0) {
        this.usm?.setAbPause?.(false);
      }

      this.lwf?.renderOnly?.();
      this.chara?.renderOnly?.();
      this.bg?.lwf?.renderOnly?.();
      this._paintHud();
      this._forgeWatchSpeed(now, performance.now() - perfStart, recording);

      void this._afterTick(tick, steps);
    };
    this.accum = 0;
    this._lastTickMs = null;
    this._wallEpochMs = null;
    this._wallStepsDone = 0;
    this.raf = requestAnimationFrame(tick);
  }

  async _afterTick(tick, steps) {
