    if (cost > 26 || gap > 60) perf.slow += 1;
    if (perf.n < 30) return;
    if (perf.slow >= 10) {
      globalThis.__forgeFastColor = true;
      this.log(`Automatic quality: switched to fast colors (${perf.slow}/${perf.n} slow frames).`);
      try { globalThis.dispatchEvent?.(new CustomEvent('forge-preview-fast')); } catch {}
    }
