    this.playing = false;
    this.pauseRemain = 0;
    if (this.raf) {
      cancelAnimationFrame(this.raf);
      this.raf = null;
    }
    this.activeEffects.clear();
    this._paintHud();
    this.onStatus?.('done', this);
    try { globalThis.dispatchEvent?.(new CustomEvent('forge-preview-done')); } catch {}

    const done = this.onDone?.(this);
    const teardown = () => {
      this.forgeVisual?.clear({preservePreloadedAssets:true});
      this.lwf?.releaseAll?.();
      this.usm?.clearClips?.();
      this.audio?.silence?.() || this.audio?.clearPlayingOnly?.();
      this._paintHud();
    };
    if (done && typeof done.then === 'function') {
      done.finally(teardown);
    } else {
      teardown();
    }
  }
  _fireAt(frame) {
    const cmds = this.commands;
