    if (this.forgeVisual?.execute(cmd)) return;
    switch (cmd.type) {
      case 'forgeTrainingItem':
        forgeActivateTraining(this, cmd);
        break;
      case 'entryEffect':
      case 'entryEffectAwaken':
      case 'entryEffectTraining':

